// Port of whisper_normalizer.english.EnglishSpellingNormalizer (whisper-normalizer 0.1.15, MIT).
// Licence and attribution: see the header of EnglishTextNormalizer.kt.
//
// The oracle reads normalizers/english.json. This port reads the same mapping, flattened to
// "british<TAB>american" lines, from the main resource english-spelling.tsv (generated by
// scripts/gen-wer-normalizer-vectors.py from the oracle's own table). Loaded once, lazily.
package com.yazses.core.bench

import java.io.IOException

internal const val SPELLING_RESOURCE = "/english-spelling.tsv"

internal class EnglishSpellingNormalizer(private val mapping: Map<String, String> = SpellingTable.mapping) {

    /** Python `" ".join(self.mapping.get(word, word) for word in s.split())`. */
    fun normalize(s: String): String = pySplit(s).joinToString(" ") { mapping[it] ?: it }
}

/** The British -> American table, read once from the classpath on first use. */
internal object SpellingTable {
    val mapping: Map<String, String> by lazy { load() }

    internal fun load(): Map<String, String> {
        val stream = SpellingTable::class.java.getResourceAsStream(SPELLING_RESOURCE)
            ?: throw IOException(
                "$SPELLING_RESOURCE is missing from the classpath; :core:bench needs it for " +
                    "Whisper English normalisation (EnglishSpellingNormalizer)",
            )
        return stream.bufferedReader(Charsets.UTF_8).use { parse(it.readLines()) }
    }

    /** Parses `british<TAB>american` lines. A later duplicate british key wins, as in the oracle's dict. */
    internal fun parse(lines: List<String>): Map<String, String> {
        val out = LinkedHashMap<String, String>()
        lines.forEachIndexed { index, line ->
            val tab = line.indexOf('\t')
            if (tab <= 0 || line.indexOf('\t', tab + 1) >= 0 || tab == line.length - 1) {
                throw IOException("$SPELLING_RESOURCE line ${index + 1} is not 'british<TAB>american'")
            }
            out[line.substring(0, tab)] = line.substring(tab + 1)
        }
        return out
    }
}
